/** Extra practice material for 1º ESO. No balance rewards are generated by this client-side bank. */
export type MainSubject='lengua'|'matematicas'|'historia'|'biologia'
export type PracticeItem={id:string;topic:string;level:1|2|3;prompt:string;answer:string;explanation:string;type:'input'|'choice';choices?:string[]}
export type PracticeChapter={id:string;title:string;description:string;items:PracticeItem[]}
const chapters:Record<MainSubject,PracticeChapter[]>={lengua:[],matematicas:[],historia:[],biologia:[]}
const add=(subject:MainSubject,code:string,title:string,description:string,questions:Omit<PracticeItem,'id'|'topic'>[])=>{
 if(questions.length!==32)throw Error(`Expected 32 original problems in ${subject}:${code}, got ${questions.length}`)
 chapters[subject].push({id:code,title,description,items:questions.map((q,i)=>({...q,id:`${subject}:${code}:${i+1}`,topic:code}))})
}
const exercise=(prompt:string,answer:string|number,explanation:string,level:1|2|3=1):Omit<PracticeItem,'id'|'topic'>=>({prompt,answer:String(answer),explanation,level,type:'input'})
const gcd=(a:number,b:number):number=>b?gcd(b,a%b):Math.abs(a)
const lcm=(a:number,b:number)=>Math.abs(a*b)/gcd(a,b)
const reduce=(n:number,d:number)=>{const g=gcd(n,d);return `${n/g}/${d/g}`}
const fmt=(n:number)=>Number(n.toFixed(4)).toString().replace('.',',')

// MATEMÁTICAS: 8 concepts x 32 genuinely parameterized questions, all free-response.
add('matematicas','enteros','Números enteros','Operaciones con negativos, temperaturas y valor absoluto.',Array.from({length:32},(_,i)=>{
 const a=2+(i*7)%19,b=1+(i*11)%16
 const mode=i%4
 if(mode===0)return exercise(`Calcula −${a} + ${b}.`,b-a,`−${a} + ${b} = ${b-a}. En la recta numérica, sumar desplaza a la derecha.`,1)
 if(mode===1)return exercise(`Un termómetro marca −${a} °C. La temperatura sube ${b} °C. ¿Cuál es la temperatura final en °C?`,b-a,`Sumamos el ascenso: −${a} + ${b} = ${b-a} °C.`,2)
 if(mode===2)return exercise(`Calcula (−${a}) − (−${b}).`,b-a,`Restar un negativo equivale a sumar: −${a} + ${b} = ${b-a}.`,2)
 return exercise(`Calcula el valor absoluto de −${a+b}.`,a+b,`|−${a+b}| = ${a+b}: distancia al cero.`,1)
}))
add('matematicas','decimales','Números decimales','Sumas, restas y productos con decimales.',Array.from({length:32},(_,i)=>{
 const a=2+(i*5)%43,b=1+(i*9)%31, mode=i%4
 if(mode===0)return exercise(`Calcula ${fmt(a/10)} + ${fmt(b/10)}.`,fmt((a+b)/10),`Alinea las comas: ${fmt(a/10)} + ${fmt(b/10)} = ${fmt((a+b)/10)}.`,1)
 if(mode===1)return exercise(`Calcula ${fmt((a+b)/10)} − ${fmt(b/10)}.`,fmt(a/10),`Al restar, quedan ${fmt(a/10)} unidades.`,1)
 if(mode===2)return exercise(`¿Cuánto es ${fmt(a/10)} × 10?`,a,`Mover la coma una posición a la derecha: ${a}.`,1)
 return exercise(`¿Cuánto es ${fmt(a/10)} × ${b}?`,fmt(a*b/10),`Multiplica ${a} × ${b} y divide entre 10: ${fmt(a*b/10)}.`,2)
}))
add('matematicas','fracciones','Fracciones','Simplificar, sumar fracciones y calcular partes.',Array.from({length:32},(_,i)=>{
 const a=2+(i*3)%9,b=2+(i*5)%7, mode=i%4
 if(mode===0)return exercise(`Simplifica la fracción ${a*2}/${b*2} (escribe a/b).`,reduce(a,b),`Divide numerador y denominador entre ${2*gcd(a,b)}: ${reduce(a,b)}.`,2)
 if(mode===1)return exercise(`¿Cuánto es ${a}/${b} + 1/${b}? Da una fracción simplificada a/b.`,reduce(a+1,b),`Mismo denominador: (${a}+1)/${b}, que se reduce a ${reduce(a+1,b)}.`,2)
 if(mode===2)return exercise(`Calcula ${a}/${b} de ${b*6} (escribe el número).`,a*6,`Divide ${b*6} entre ${b} y multiplica por ${a}: ${a*6}.`,1)
 return exercise(`¿Cuánto es ${a}/${b} × ${b}/2? Da una fracción simplificada a/b.`,reduce(a,2),`Se cancela el ${b} y queda ${a}/2 = ${reduce(a,2)}.`,3)
}))
add('matematicas','potencias','Potencias y divisibilidad','Powers, divisors, GCD and LCM.',Array.from({length:32},(_,i)=>{
 const k=Math.floor(i/4),a=2+k,b=2+(k*5)%7,mode=i%4
 if(mode===0)return exercise(`Calcula ${a}².`,a*a,`${a}² = ${a} × ${a} = ${a*a}.`,1)
 if(mode===1)return exercise(`Calcula ${a}³.`,a*a*a,`${a}³ = ${a} × ${a} × ${a} = ${a*a*a}.`,2)
 if(mode===2)return exercise(`Halla el máximo común divisor de ${a*4} y ${b*4}.`,gcd(a*4,b*4),`El MCD de ${a*4} y ${b*4} es ${gcd(a*4,b*4)}.`,3)
 return exercise(`Halla el mínimo común múltiplo de ${a} y ${b}.`,lcm(a,b),`El menor múltiplo compartido de ${a} y ${b} es ${lcm(a,b)}.`,3)
}))
add('matematicas','porcentajes','Porcentajes y proporcionalidad','Descuentos, aumentos y proporciones directas.',Array.from({length:32},(_,i)=>{
 const a=2+(i*7)%19, b=1+(i*3)%12, mode=i%4
 if(mode===0)return exercise(`Calcula el 10 % de ${a*10}.`,a,`10 % equivale a una décima parte: ${a}.`,1)
 if(mode===1)return exercise(`Una camiseta cuesta ${a*10} € y tiene un descuento del 20 %. ¿Cuánto cuesta después?`,a*8,`El 80 % de ${a*10} es ${a*8} €.`,2)
 if(mode===2)return exercise(`Si ${a} cuadernos cuestan ${a*b} €, ¿cuánto cuestan 3 cuadernos?`,3*b,`Cada cuaderno cuesta ${b} €. Tres cuestan ${3*b} €.`,2)
 return exercise(`Un número aumenta un 25 % y pasa a ${a*5}. ¿Cuál era antes del aumento?`,a*4,`Si el original es ${a*4}, su 25 % es ${a}, total ${a*5}.`,3)
}))
add('matematicas','ecuaciones','Ecuaciones iniciales','Despeja x usando operaciones inversas.',Array.from({length:32},(_,i)=>{
 const x=2+(i*7)%26,b=3+(i*9)%31,a=2+(i*5)%8, mode=i%4
 if(mode===0)return exercise(`Resuelve: x + ${b} = ${x+b}. ¿Cuánto vale x?`,x,`Restamos ${b} en ambos lados: x = ${x}.`,1)
 if(mode===1)return exercise(`Resuelve: x − ${b} = ${x-b}. ¿Cuánto vale x?`,x,`Sumamos ${b} a ambos lados: x = ${x}.`,1)
 if(mode===2)return exercise(`Resuelve: ${a}x = ${a*x}. ¿Cuánto vale x?`,x,`Dividimos ambos miembros entre ${a}: x = ${x}.`,2)
 return exercise(`Resuelve: ${a}x + ${b} = ${a*x+b}. ¿Cuánto vale x?`,x,`Restamos ${b} y dividimos entre ${a}: x = ${x}.`,3)
}))
add('matematicas','geometria','Geometría','Perímetros, superficies y ángulos.',Array.from({length:32},(_,i)=>{
 const a=3+(i*7)%18,b=2+(i*11)%15,mode=i%4
 if(mode===0)return exercise(`Perímetro de un cuadrado de lado ${a} cm. Responde solo el número.`,4*a,`Cuatro lados iguales: 4 × ${a} = ${4*a} cm.`,1)
 if(mode===1)return exercise(`Área de un rectángulo de ${a} cm por ${b} cm. Responde solo el número.`,a*b,`Área = ${a} × ${b} = ${a*b} cm².`,1)
 if(mode===2)return exercise(`Área de un triángulo de base ${a*2} cm y altura ${b} cm. Responde solo el número.`,a*b,`(${a*2} × ${b}) / 2 = ${a*b} cm².`,2)
 return exercise(`Dos ángulos suman 180°. Si uno mide ${a*5}°, ¿cuánto mide el otro?`,180-a*5,`Son suplementarios: 180 − ${a*5} = ${180-a*5}°.`,2)
}))
add('matematicas','estadistica','Estadística','Media, mediana, moda y rango.',Array.from({length:32},(_,i)=>{
 const k=Math.floor(i/4),a=2+k*3,b=2+(k*7)%13,mode=i%4
 if(mode===0)return exercise(`Calcula la media aritmética de ${a}, ${a+2} y ${a+4}.`,a+2,`(${a}+${a+2}+${a+4})/3 = ${a+2}.`,1)
 if(mode===1)return exercise(`Calcula el rango de estos datos: ${a}, ${a+b}, ${a+2*b}.`,2*b,`Máximo − mínimo = ${a+2*b} − ${a} = ${2*b}.`,1)
 if(mode===2)return exercise(`Halla la moda de ${a}, ${b}, ${a}, ${a+1}, ${a}.`,a,`${a} aparece tres veces: es la moda.`,2)
 return exercise(`Mediana de los valores ${a}, ${a+3}, ${a+6}, ${a+9}, ${a+12}.`,a+6,`Ordenados, el valor central (tercero) es ${a+6}.`,2)
}))

