export const MAIN_PRACTICE=chapters
export const getPracticeBank=(subject:MainSubject)=>chapters[subject]
export const practiceCount=(subject:MainSubject)=>chapters[subject].reduce((n,x)=>n+x.items.length,0)
export const allPractice=(subject:MainSubject)=>chapters[subject].flatMap(chapter=>chapter.items)
/** Human typed answers are normalized for case, accent, whitespace, comma decimal and equivalent fractions. */
export function normalizePracticeAnswer(answer:string){return answer.toLocaleLowerCase('es-ES').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[‘’´`]/g,"'").replace(/\s+/g,' ').trim().replace(/\s*\/\s*/g,'/').replace(/\.$/,'')}
function parseNumber(input:string):number|null{
 const clean=normalizePracticeAnswer(input).replace(',','.').replace(/\s*(?:€|cm²|cm|°c|°|km)\s*$/,'').trim()
 const fraction=clean.match(/^(-?\d+)\/(-?\d+)$/)
 if(fraction){const denominator=Number(fraction[2]);return denominator!==0?Number(fraction[1])/denominator:null}
 if(!/^-?\d+(?:\.\d+)?$/.test(clean))return null
 const v=Number(clean);return Number.isFinite(v)?v:null
}
export function checkPracticeAnswer(item:PracticeItem,input:string){
 const text=normalizePracticeAnswer(input)
 if(!text)return false
 const candidates=item.answer.split('|').map(normalizePracticeAnswer)
 if(candidates.includes(text))return true
 if(item.topic==='sinonimos'||item.topic==='antonimos')return false
 const a=parseNumber(input)
 return a!==null&&candidates.some(c=>{const b=parseNumber(c);return b!==null&&Math.abs(b-a)<1e-8})
}
/** Deterministic shuffle from a unique attempt seed. Never the old repeating A-B-C order. */
export function shufflePractice<T>(data:readonly T[],seed:string):T[]{
 const out=[...data];let state=2166136261
 for(let i=0;i<seed.length;i++){state^=seed.charCodeAt(i);state=Math.imul(state,16777619)>>>0}
 for(let i=out.length-1;i>0;i--){state=(Math.imul(state,1664525)+1013904223)>>>0;const j=state%(i+1);[out[i],out[j]]=[out[j],out[i]]}
 return out
}
